import{_ as i,c as e,o as t,ag as s}from"./chunks/framework.BeChtK_P.js";const o="/assets/digikam-geo-editor.B2JyWIEo.png",d="/assets/digikam-config-meta.CtP4knUL.png",h=JSON.parse('{"title":"Digikam给照片批量添加地理信息","description":"","frontmatter":{"title":"Digikam给照片批量添加地理信息","author":"welpher.yu","date":"2025-03-31T15:47:11.000Z","tags":["照片"],"categories":["居家折腾"]},"headers":[],"relativePath":"posts/2025/digikam-batch-add-geotags.md","filePath":"posts/2025/digikam-batch-add-geotags.md"}'),c={name:"posts/2025/digikam-batch-add-geotags.md"};function p(g,a,m,r,n,l){return t(),e("div",null,[...a[0]||(a[0]=[s('<p>我在家部了immich来进行照片管理，但是发现immich没有批量添加地理信息的功能，于是我就想到了digikam，digikam是一个开源的相册管理软件，它支持批量添加地理信息，但是需要一些配置。我是直接在用docker的方式安装了Digikam，这里就不作介绍如何安装Digikam了。</p><h2 id="digikam给照片批量添加地理信息" tabindex="-1">Digikam给照片批量添加地理信息 <a class="header-anchor" href="#digikam给照片批量添加地理信息" aria-label="Permalink to &quot;Digikam给照片批量添加地理信息&quot;">​</a></h2><p>首先，选中你要添加地理位置的照片，然后点击菜单中<code>项目-添加地理位置...</code>,进入到地理位置编辑器 <img src="'+o+'" alt="地理位置编辑器"></p><p>然后，有两种方式，一种是在有地理信息的照片列表中选择照片右键，然后点击复制坐标，然后选中要添加地理位置的照片，点击粘贴坐标，然后确定，地理信息就添加到照片中了。</p><p>对于没有同地理信息的照片，你可以在地图上，找到你要添加的地理信息，然后以下面的这种信息生成一个文本</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>geo:纬度,经度,海拔高度</span></span></code></pre></div><p>复制这个文本，然后在地理位置编辑器中，选中要添加地理位置的照片，点击粘贴坐标，然后确定，地理信息也就添加到照片中了。</p><h2 id="遇到的问题" tabindex="-1">遇到的问题 <a class="header-anchor" href="#遇到的问题" aria-label="Permalink to &quot;遇到的问题&quot;">​</a></h2><p>只是按照上面的方法，最后也只是把地理信息添加到digikam的数据库中了，没有在照片中。需要设置Digikam，在<code>设置-配置digikam</code>, 左边选择<code>元数据</code>,勾选地理位置信息，这样，你再按照之前的操作就能把信息写入到照片里了。 <img src="'+d+'" alt="配置"></p>',9)])])}const _=i(c,[["render",p]]);export{h as __pageData,_ as default};
